package com.worklink.service;import com.worklink.dto.matching.MatchResult;import com.worklink.entity.*;import com.worklink.entity.enums.*;import com.worklink.repository.*;import org.springframework.stereotype.Service;import java.math.*;import java.util.*;
@Service public class MatchingScoringService {final ProjectSkillRepository ps;final FreelancerSkillRepository fs;final PortfolioProjectRepository pp;final ProposalRepository pr;public MatchingScoringService(ProjectSkillRepository a,FreelancerSkillRepository b,PortfolioProjectRepository c,ProposalRepository d){ps=a;fs=b;pp=c;pr=d;}
 public MatchResult score(Project p,FreelancerProfile f){var req=ps.findByProjectId(p.getId());var capabilities=fs.findByFreelancerId(f.getId());Map<Long,FreelancerSkill> have=new HashMap<>();for(var x:capabilities)have.put(x.getSkill().getId(),x);double total=0,matched=0,prof=0;List<String> yes=new ArrayList<>(),no=new ArrayList<>();for(var x:req){double w=x.getImportance()==SkillImportance.REQUIRED?1:x.getImportance()==SkillImportance.IMPORTANT?.7:.4;total+=w;var h=have.get(x.getSkill().getId());if(h!=null){matched+=w;prof+=w*level(h.getProficiencyLevel());yes.add(x.getSkill().getName());}else no.add(x.getSkill().getName());}double skill=total==0?0:100*matched/total, proficiency=total==0?0:prof/total;double exp=p.getRequiredExperience()==0?100:Math.min(100,100d*f.getYearsOfExperience()/p.getRequiredExperience());String text=String.join(" ",pp.findByFreelancerId(f.getId()).stream().map(x->String.join(" ",Objects.toString(x.getTitle(),""),Objects.toString(x.getDescription(),""),Objects.toString(x.getTechnologies(),""))).toList()).toLowerCase();double portfolio=req.isEmpty()?0:100d*req.stream().filter(x->text.contains(x.getSkill().getName().toLowerCase())).count()/req.size();var proposal=pr.findByProjectIdAndFreelancerId(p.getId(),f.getId());BigDecimal rate=proposal.map(Proposal::getProposedAmount).orElse(f.getHourlyRate());double budget=rate==null?50:(rate.compareTo(p.getBudgetMax())<=0?100:Math.max(0,100-100d*rate.subtract(p.getBudgetMax()).doubleValue()/p.getBudgetMax().doubleValue()));double finalScore=.4*skill+.2*proficiency+.15*exp+.1*portfolio+.15*budget;String explain=(yes.isEmpty()?"Limited skill overlap": "Strong match")+": "+yes.size()+"/"+req.size()+" requested skills matched"+(no.isEmpty()?".": "; missing "+String.join(", ",no)+".");return new MatchResult(f.getId(),f.getUser().getFirstName()+" "+f.getUser().getLastName(),round(finalScore),round(skill),round(proficiency),round(exp),round(portfolio),round(budget),yes,no,explain);}
 double level(SkillProficiency p){return switch(p){case BEGINNER->25;case INTERMEDIATE->50;case ADVANCED->75;case EXPERT->100;};}double round(double x){return Math.round(x*100d)/100d;}}
